            cy=sum(y for y,x in cells)/len(cells); cx=sum(x for y,x in cells)/len(cells)
            q=('T' if cy<h/2 else 'B')+('L' if cx<w/2 else 'R')
            objs.append((q,color,shape))
    # Move TL and BR objects into the left output column; TR and BL into right.
    # The upper slot receives BR/TR; lower slot receives TL/BL.
    slots={'TL':(7,0),'BR':(4,0),'TR':(6,5),'BL':(7,5)}
